return new { play=UnityEditor.EditorApplication.isPlaying, scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path, runners=UnityEngine.Object.FindObjectsByType<UnityEngine.MonoBehaviour>(UnityEngine.FindObjectsSortMode.None).Select(c=>c.GetType().FullName).Where(n=>n.Contains("Test") || n.Contains("Runner")).Distinct().ToArray(), width=UnityEngine.Screen.width, height=UnityEngine.Screen.height };
